import { Component, OnInit } from '@angular/core';
import { BillService } from '../../services/bill-service';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { InvoiceService } from '../../services/invoice-service';
import { Invoice } from '../../models/invoice';

export interface Bill {
  orderNo: string;
  fullName: string;
  mobile: string;
  email: string;
  orderDate: string;
}

@Component({
  standalone: true,
  selector: 'app-invoice',
  templateUrl: './Invoice.html',
  imports:[CommonModule, FormsModule, RouterLink],
})
export class InvoiceComponent implements OnInit {
  bills: Invoice[] = [];
  searchTerm = '';

  constructor(private billService: InvoiceService) {}

  ngOnInit() {
    this.billService.getCompletedInvoices().subscribe(data => {
      this.bills = data;
      console.log(data)
    });
  }

  filteredBills() {
    const term = this.searchTerm.toLowerCase();
    return this.bills.filter(b =>
      b.orderDispatch?.invoiceNo.toPrecision().includes(term) ||
      b.orderDispatch?.customerName.toLowerCase().includes(term) ||
      b.orderDispatch?.customerPhone.toPrecision().includes(term) ||
      b.orderDispatch?.customerEmail.toLowerCase().includes(term) ||
      b.orderDispatch?.orderDate.toLowerCase().includes(term)
    );
  }
}
